1	/**
2	 * Centralized Resend email service.
3	 *
4	 * All send functions return `true` on success, `false` on failure — they never
5	 * throw. This lets callers fire-and-forget without wrapping in try/catch.
6	 */
7	import { Resend } from "resend";
8	
9	// ---------------------------------------------------------------------------
10	// Types
11	// ---------------------------------------------------------------------------
12	
13	export interface EmailOptions {
14	  /** Display name in the From field (e.g. "Cool Store"). Defaults to shopDisplayName. */
15	  senderName?: string | null;
16	  /** Cached Shopify store display name (from ShopSettings.shopName). Falls back to myshopify slug. */
17	  shopDisplayName?: string | null;
18	  /** Reply-to email for customer-facing emails. If empty, no reply-to header is added. */
19	  replyTo?: string | null;
20	}
21	
22	// ---------------------------------------------------------------------------
23	// Client singleton
24	// ---------------------------------------------------------------------------
25	
26	let client: Resend | null = null;
27	
28	function getClient(): Resend | null {
29	  if (client) return client;
30	  const apiKey = process.env.RESEND_API_KEY;
31	  if (!apiKey) {
32	    console.warn("[email] RESEND_API_KEY not set — emails will be skipped");
33	    return null;
34	  }
35	  client = new Resend(apiKey);
36	  return client;
37	}
38	
39	function getRawFromEmail(): string {
40	  return process.env.RESEND_FROM_EMAIL || "noreply@example.com";
41	}
42	
43	function shopFallbackName(shop: string, options?: EmailOptions): string {
44	  return options?.shopDisplayName?.trim() || shop.replace(".myshopify.com", "");
45	}
46	
47	/**
48	 * Build the full From address with display name.
49	 *
50	 * - Custom sender name set:  "Cool Store via Pinzo <noreply@boldteq.app>"
51	 * - No custom name:          "cool-store via Pinzo <noreply@boldteq.app>"
52	 */
53	function buildFrom(shop: string, options?: EmailOptions): string {
54	  const displayName = options?.senderName?.trim() || shopFallbackName(shop, options);
55	  return `${displayName} via Pinzo <${getRawFromEmail()}>`;
56	}
57	
58	/**
59	 * Build optional reply_to field. Returns undefined when not configured
60	 * so it can be spread into the Resend payload without adding an empty header.
61	 */
62	function buildReplyTo(options?: EmailOptions): { reply_to: string } | Record<string, never> {
63	  const replyTo = options?.replyTo?.trim();
64	  if (replyTo) return { reply_to: replyTo };
65	  return {};
66	}
67	
68	/**
69	 * Wrap email body content in a branded layout with Pinzo logo header and store name.
70	 */
71	const APP_URL = process.env.SHOPIFY_APP_URL || "https://zip-code-checker-production-b1a0.up.railway.app";
72	
73	function emailLayout(storeName: string, body: string): string {
74	  return `
75	    <div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;margin:0 auto;background:#ffffff">
76	      <div style="padding:24px 24px 16px;border-bottom:1px solid #e5e7eb;text-align:center">
77	        <table cellpadding="0" cellspacing="0" border="0" style="margin:0 auto">
78	          <tr>
79	            <td style="vertical-align:middle;padding-right:10px">
80	              <img src="${APP_URL}/pinzo-logo.svg" alt="Pinzo" width="36" height="36" style="display:block;border-radius:8px" />
81	            </td>
82	            <td style="vertical-align:middle">
83	              <span style="font-size:20px;font-weight:700;color:#1a1a1a;letter-spacing:-0.3px">Pinzo</span>
84	            </td>
85	          </tr>
86	        </table>
87	        <p style="margin:8px 0 0;font-size:13px;color:#6b7280">${storeName}</p>
88	      </div>
89	      <div style="padding:24px">
90	        ${body}
91	      </div>
92	      <div style="padding:16px 24px;border-top:1px solid #e5e7eb;text-align:center">
93	        <p style="margin:0;font-size:12px;color:#9ca3af">Powered by <span style="color:#008060;font-weight:600">Pinzo</span></p>
94	      </div>
95	    </div>
96	  `;
97	}
