99	// ---------------------------------------------------------------------------
100	// 1. Waitlist Confirmation  (App → Customer)
101	// ---------------------------------------------------------------------------
102	
103	export async function sendWaitlistConfirmation(
104	  to: string,
105	  zipCode: string,
106	  shop: string,
107	  options?: EmailOptions,
108	): Promise<boolean> {
109	  const resend = getClient();
110	  if (!resend) return false;
111	
112	  const name = options?.senderName?.trim() || shopFallbackName(shop, options);
113	
114	  try {
115	    await resend.emails.send({
116	      from: buildFrom(shop, options),
117	      to,
118	      subject: `You're on the waitlist — ${name}`,
119	      html: emailLayout(name, `
120	          <h2 style="margin:0 0 16px;color:#1a1a1a">You're on the waitlist!</h2>
121	          <p style="color:#374151;line-height:1.6">Thanks for signing up. We'll let you know as soon as delivery is available to <strong>${zipCode}</strong>.</p>
122	          <p style="color:#6b7280;font-size:13px;margin-top:24px">— ${name}</p>
123	      `),
124	      text: `You're on the waitlist!\n\nThanks for signing up. We'll let you know as soon as delivery is available to ${zipCode}.\n\n— ${name}`,
125	      ...buildReplyTo(options),
126	    });
127	    return true;
128	  } catch (error) {
129	    console.error("[email] Failed to send waitlist confirmation:", error);
130	    return false;
131	  }
132	}
