312	// Handle POST requests with JSON body: { shop, zip }
313	export const action = async ({ request }: ActionFunctionArgs) => {
314	  let shop: string | null = null;
315	  let zip: string | null = null;
316	
317	  try {
318	    const body = await request.json();
319	    shop = body?.shop ?? null;
320	    zip = body?.zip ?? null;
321	  } catch {
322	    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
323	      status: 400,
324	      headers: CORS_HEADERS,
325	    });
326	  }
327	
328	  return handleZipCheck(shop, zip);
329	};
