305	// ── Scope custom CSS for admin preview — prefix selectors with #wid ─────────
306	function scopeAdminCss(rawCss: string | null | undefined, wid: string): string {
307	  if (!rawCss) return "";
308	  const css = rawCss.replace(/<\/style>/gi, "");
309	  let result = "";
310	  let remaining = css;
311	  while (remaining.length > 0) {
312	    const openBrace = remaining.indexOf("{");
313	    if (openBrace === -1) break;
314	    const closeBrace = remaining.indexOf("}", openBrace);
315	    if (closeBrace === -1) break;
316	    const selector = remaining.substring(0, openBrace).trim();
317	    const body = remaining.substring(openBrace + 1, closeBrace);
318	    remaining = remaining.substring(closeBrace + 1);
319	    if (selector.startsWith("@")) {
320	      result += selector + "{" + body + "}";
321	    } else if (selector) {
322	      const prefixed = selector.split(",").map(s => {
323	        s = s.trim();
324	        return s ? "#" + wid + " " + s : "";
325	      }).filter(Boolean).join(", ");
326	      result += prefixed + " {" + body + "}";
327	    }
328	  }
329	  return result;
330	}
