304	
305	  const isDowngrade =
306	    !isCurrent &&
307	    plan.id !== "free" &&
308	    (TIER_ORDER[plan.id] ?? 0) < (TIER_ORDER[currentTier] ?? 0);
309	
310	  const shopifyPlan = isAnnual
311	    ? plan.shopifyPlanAnnual
312	    : plan.shopifyPlanMonthly;
