376	            <InlineStack gap="100" blockAlign="baseline" wrap={false}>
377	              <Text as="p" variant="heading2xl" fontWeight="bold">
378	                ${displayPrice}
379	              </Text>
380	              <Text as="p" variant="bodyMd" tone="subdued">
381	                /mo
382	              </Text>
383	            </InlineStack>
384	            <Text as="p" variant="bodyMd" tone="subdued">
